import{_ as t,a as r,o as a,a6 as s}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Returns (RMA)","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/shop/returns/index.md","filePath":"api/rest-api/shop/returns/index.md","lastUpdated":1786429091000}'),n={name:"api/rest-api/shop/returns/index.md"};function o(d,e,i,h,l,u){return a(),r("div",null,e[0]||(e[0]=[s('<h1 id="returns-rma" tabindex="-1">Returns (RMA) <a class="header-anchor" href="#returns-rma" aria-label="Permalink to &quot;Returns (RMA)&quot;">​</a></h1><p>Returns — also called RMA (Return Merchandise Authorization) — let a logged-in customer ask the store to take back or cancel an item they ordered. A customer can raise a return for an eligible item, converse with the store about it through a message thread, and cancel, reopen or close the request. Every return is scoped to the customer who owns it; a customer can only ever see and act on their own returns.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>All return endpoints require an authenticated <strong>customer</strong> — provide the storefront key and a customer Bearer token. See the <a href="/api/rest-api/authentication.html">Authentication</a> page for how to obtain and send them.</p><h2 id="returns-must-be-switched-on-first" tabindex="-1">Returns must be switched on first <a class="header-anchor" href="#returns-must-be-switched-on-first" aria-label="Permalink to &quot;Returns must be switched on first&quot;">​</a></h2><p>Returns are off out of the box. Nothing in the API errors when they are — <a href="/api/rest-api/shop/returns/list-returnable-items.html"><code>GET /api/shop/returnable-items</code></a> simply comes back empty, and a client sees an order with no returnable rows rather than a message explaining why. Three things have to line up, all configured on the admin side:</p><table tabindex="0"><thead><tr><th>Requirement</th><th>Where it lives</th><th>Effect when unset</th></tr></thead><tbody><tr><td><strong>Allowed product types</strong></td><td>Configuration → Sales → RMA → <em>Allowed product types</em></td><td>An empty setting makes <strong>nothing</strong> returnable — it does not mean &quot;all types&quot;. A product whose type is absent from the list is never eligible.</td></tr><tr><td><strong>Allow RMA on the product</strong></td><td>The product&#39;s own <code>allow_rma</code> attribute, off by default</td><td>That product&#39;s order items are never returnable.</td></tr><tr><td><strong>Return window</strong></td><td>The product&#39;s active RMA rule, otherwise Configuration → Sales → RMA → <em>Default allow days</em> (default <code>7</code>)</td><td>Falls back to the configured default.</td></tr></tbody></table><p>The decision is made <strong>when the order is placed</strong>, not when the return is requested: the resolved window is written onto the order item and frozen there. Enabling RMA later therefore does not make existing orders returnable — only orders placed after the change qualify. A client testing the flow against pre-existing orders will see an empty list no matter how the settings are changed.</p><p>An item then stays returnable while the order date plus that window has not passed, and while some quantity remains unrefunded and uncanceled.</p><h2 id="how-a-return-works" tabindex="-1">How a return works <a class="header-anchor" href="#how-a-return-works" aria-label="Permalink to &quot;How a return works&quot;">​</a></h2><ol><li><strong>Find eligible items.</strong> Call <a href="/api/rest-api/shop/returns/list-returnable-items.html"><code>GET /api/shop/returnable-items</code></a> for an order to see which items are still within their return window and how many units can be returned or canceled.</li><li><strong>Pick a reason.</strong> Call <a href="/api/rest-api/shop/returns/list-return-reasons.html"><code>GET /api/shop/return-reasons</code></a> for the resolution type (<code>return</code> or <code>cancel_items</code>) to get the reason ids to choose from.</li><li><strong>Raise the return.</strong> Call <a href="/api/rest-api/shop/returns/create-return.html"><code>POST /api/shop/returns</code></a> with the order, the item, a quantity, the resolution type and a reason id. The return starts in a <code>Pending</code> status.</li><li><strong>Converse.</strong> Read the thread with <a href="/api/rest-api/shop/returns/list-return-messages.html"><code>GET /api/shop/return-messages</code></a> and add messages with <a href="/api/rest-api/shop/returns/send-return-message.html"><code>POST /api/shop/return-messages</code></a>.</li><li><strong>Cancel, reopen or close.</strong> Use <a href="/api/rest-api/shop/returns/cancel-return.html">cancel</a>, <a href="/api/rest-api/shop/returns/reopen-return.html">reopen</a> or <a href="/api/rest-api/shop/returns/close-return.html">close</a> to change the state of the request.</li></ol><h2 id="status-flags" tabindex="-1">Status flags <a class="header-anchor" href="#status-flags" aria-label="Permalink to &quot;Status flags&quot;">​</a></h2><p>Each return carries three action flags that tell a client which operations are currently allowed:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>canClose</code></td><td>The return can be closed (marked solved) by the customer.</td></tr><tr><td><code>canReopen</code></td><td>The return can be reopened back to pending.</td></tr><tr><td><code>isExpired</code></td><td>The return is past its allowed action window.</td></tr></tbody></table><p>These flags are populated on the single-return view; on the list they come back <code>null</code>.</p><h2 id="quantity-caps-are-enforced-by-the-store" tabindex="-1">Quantity caps are enforced by the store <a class="header-anchor" href="#quantity-caps-are-enforced-by-the-store" aria-label="Permalink to &quot;Quantity caps are enforced by the store&quot;">​</a></h2><p>When raising a return, the quantity you send is capped server-side by the trusted quantity a customer is actually allowed to return or cancel for that item (<code>forReturnQuantity</code> / <code>forCancelQuantity</code> from <code>returnable-items</code>). You can never return more units than were ordered and are still eligible.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Method &amp; Path</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/rest-api/shop/returns/list-returns.html">List own returns</a></td><td><code>GET /api/shop/returns</code></td><td>The customer&#39;s own returns, newest first.</td></tr><tr><td><a href="/api/rest-api/shop/returns/view-return.html">View one return</a></td><td><code>GET /api/shop/returns/{id}</code></td><td>A single return the customer owns.</td></tr><tr><td><a href="/api/rest-api/shop/returns/create-return.html">Raise a return</a></td><td><code>POST /api/shop/returns</code></td><td>Create a new return for one order item.</td></tr><tr><td><a href="/api/rest-api/shop/returns/cancel-return.html">Cancel a return</a></td><td><code>POST /api/shop/returns/{id}/cancel</code></td><td>Cancel the customer&#39;s own return.</td></tr><tr><td><a href="/api/rest-api/shop/returns/reopen-return.html">Reopen a return</a></td><td><code>POST /api/shop/returns/{id}/reopen</code></td><td>Reopen a canceled/declined return.</td></tr><tr><td><a href="/api/rest-api/shop/returns/close-return.html">Close a return</a></td><td><code>POST /api/shop/returns/{id}/close</code></td><td>Mark a return solved.</td></tr><tr><td><a href="/api/rest-api/shop/returns/list-returnable-items.html">List returnable items</a></td><td><code>GET /api/shop/returnable-items</code></td><td>Return-eligible items of one of the customer&#39;s orders.</td></tr><tr><td><a href="/api/rest-api/shop/returns/list-return-reasons.html">List return reasons</a></td><td><code>GET /api/shop/return-reasons</code></td><td>Active reasons for a resolution type.</td></tr><tr><td><a href="/api/rest-api/shop/returns/list-return-messages.html">List return messages</a></td><td><code>GET /api/shop/return-messages</code></td><td>The conversation thread of a return.</td></tr><tr><td><a href="/api/rest-api/shop/returns/send-return-message.html">Send a message</a></td><td><code>POST /api/shop/return-messages</code></td><td>Add a message to the return conversation.</td></tr></tbody></table>',19)]))}const m=t(n,[["render",o]]);export{p as __pageData,m as default};
